package com.crypto.validation

import scala.concurrent.{Future, ExecutionContext}
import scala.util.matching.Regex
import scala.util.{Try, Success, Failure}
import java.security.MessageDigest
import javax.crypto.Cipher
import javax.crypto.spec.{SecretKeySpec, IvParameterSpec}
import java.util.Base64

object CryptoConfig {
  val AES_KEY_SIZE = 256
  val IV_SIZE = 16
  val SUPPORTED_ALGORITHMS = Set("AES/CBC/PKCS5Padding", "AES/GCM/NoPadding")
}

trait CertificateValidator {
  def validateCertChain(pemChain: String)(implicit ec: ExecutionContext): Future[Boolean]
}

class PemFormatValidator extends CertificateValidator {

  // PEM header/footer validation pattern
  // Validates the structure: BEGIN marker, base64 content, END marker
  // with optional attributes between markers
  private val pemBlockPattern: Regex = 
    """(?s)-----BEGIN\s+((?:[A-Z]+\s*)+)-----([\s\S]*?)-----END\s+\1-----""".r

  // Validates base64 content structure within PEM blocks
  // Uses atomic grouping equivalent to prevent backtracking
  private val base64ContentPattern: Regex =
    """^[A-Za-z0-9+/\s]*={0,2}\s*$""".r

  // X.509 extension OID pattern for critical extensions
  private val oidPattern: Regex =
    """(\d+\.)+\d+""".r

  // Subject Alternative Name validation
  // Matches DNS names, IPs, and email addresses in SAN fields
  // Rewritten to a linear, non-ambiguous form to avoid catastrophic backtracking.
  private val sanPattern: Regex =
    """(?:DNS|IP|email):([A-Za-z0-9][A-Za-z0-9.-]*)""".r

  // Certificate serial number hex pattern
  private val serialPattern: Regex =
    """(?i)^(?:[0-9a-f]{2}:)*[0-9a-f]{2}$""".r

  private val MAX_INPUT_LENGTH = 65536

  private def extractPemBlocks(input: String): Seq[String] = {
    if (input.length > MAX_INPUT_LENGTH) return Seq.empty
    pemBlockPattern.findAllMatchIn(input).map(_.group(2).trim).toSeq
  }

  private def validateBase64Content(content: String): Boolean = {
    if (content.length > MAX_INPUT_LENGTH) return false
    base64ContentPattern.findFirstIn(content).isDefined
  }

  private def validateExtensions(extensionData: String): Boolean = {
    if (extensionData.length > MAX_INPUT_LENGTH) return false
    val oids = oidPattern.findAllIn(extensionData).toSeq
    oids.nonEmpty && oids.forall(_.split("\\.").length >= 3)
  }

  private def validateSAN(sanField: String): Boolean = {
    if (sanField.length > MAX_INPUT_LENGTH) return false
    sanPattern.findAllMatchIn(sanField).nonEmpty
  }

  private def computeFingerprint(derBytes: Array[Byte]): String = {
    val digest = MessageDigest.getInstance("SHA-256")
    digest.digest(derBytes).map("%02x".format(_)).mkString(":")
  }

  private def validateSerialNumber(serial: String): Boolean = {
    if (serial.length > 1024) return false
    serialPattern.findFirstIn(serial.trim).isDefined
  }

  def validateCertChain(pemChain: String)(implicit ec: ExecutionContext): Future[Boolean] = {
    Future {
      val blocks = extractPemBlocks(pemChain)
      if (blocks.isEmpty) {
        false
      } else {
        blocks.forall { block =>
          validateBase64Content(block) && {
            Try(Base64.getMimeDecoder.decode(block)) match {
              case Success(decoded) =>
                val fingerprint = computeFingerprint(decoded)
                fingerprint.nonEmpty
              case Failure(_) => false
            }
          }
        }
      }
    }
  }

  def validateCertificateMetadata(
    serial: String,
    extensions: String,
    san: String
  )(implicit ec: ExecutionContext): Future[Boolean] = {
    Future {
      validateSerialNumber(serial) &&
      validateExtensions(extensions) &&
      validateSAN(san)
    }
  }
}

class AsyncCryptoService(validator: PemFormatValidator)(implicit ec: ExecutionContext) {

  def processEncryptedPayload(
    encryptedData: String,
    pemCert: String,
    metadata: Map[String, String]
  ): Future[Either[String, Array[Byte]]] = {

    val validationFuture = for {
      certValid <- validator.validateCertChain(pemCert)
      metaValid <- validator.validateCertificateMetadata(
        metadata.getOrElse("serial", ""),
        metadata.getOrElse("extensions", ""),
        metadata.getOrElse("san", "")
      )
    } yield certValid && metaValid

    validationFuture.map {
      case true =>
        Try(Base64.getDecoder.decode(encryptedData)) match {
          case Success(decoded) => Right(decoded)
          case Failure(e) => Left(s"Decoding failed: ${e.getMessage}")
        }
      case false =>
        Left("Certificate validation failed")
    }.recover {
      case e: Exception => Left(s"Processing error: ${e.getMessage}")
    }
  }
}
